-- Migração do motoboy pra Supabase Auth de verdade (login por password_hash/JWT
-- próprio vira legado). motoboys.user_id já existia (20260714000002) mas nada
-- garantia unicidade — o novo guard depende de um lookup único por user_id.
CREATE UNIQUE INDEX IF NOT EXISTS motoboys_user_id_unique
  ON public.motoboys (user_id) WHERE user_id IS NOT NULL;

COMMENT ON COLUMN public.motoboys.password_hash IS
  'Legado — pré-migração pra Supabase Auth. Não lido/escrito em novos fluxos.';
COMMENT ON COLUMN public.motoboys.access_token IS
  'Legado — token estático de link de cadastro pré-senha. Não lido/escrito em novos fluxos.';

-- Estende o trigger que já sincroniza user_profiles.email quando auth.users.email
-- muda (20260813000003) pra também manter motoboys.email em dia, já que e-mail
-- passa a ser a identidade de login do motoboy.
CREATE OR REPLACE FUNCTION public.sync_user_profile_email()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    UPDATE public.user_profiles SET email = NEW.email, updated_at = now() WHERE id = NEW.id;
    UPDATE public.motoboys SET email = NEW.email WHERE user_id = NEW.id;
    RETURN NEW;
END;
$$;

-- Nota: a política RLS `motoboys_owner` (20260607000003) ainda referencia a coluna
-- legada `restaurant_id`, não `criado_por_restaurant_id`/`motoboy_estabelecimentos`.
-- Na prática é código morto: SupabaseService sempre usa a service-role key (ignora
-- RLS) e nenhum código do frontend consulta `motoboys` com a anon key. Deixado como
-- está de propósito — fora do escopo desta migração, cabe uma limpeza à parte.

-- Vincula o motoboy a uma conta de cliente (Supabase Auth), quando o cadastro de
-- motoboy é feito por alguém já logado como cliente. Usado pra promover
-- user_profiles.role pra 'motoboy' automaticamente nesse caso.
ALTER TABLE public.motoboys
  ADD COLUMN IF NOT EXISTS user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_motoboys_user_id ON public.motoboys (user_id) WHERE user_id IS NOT NULL;

-- Afiliação N:N entre motoboy e estabelecimento: motoboy solicita, estabelecimento aceita/recusa.
CREATE TABLE IF NOT EXISTS public.motoboy_estabelecimentos (
  id             BIGSERIAL PRIMARY KEY,
  motoboy_id     BIGINT NOT NULL REFERENCES public.motoboys(id) ON DELETE CASCADE,
  restaurant_id  BIGINT NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
  status         TEXT NOT NULL DEFAULT 'pendente' CHECK (status IN ('pendente','aceito','recusado','removido')),
  motivo_recusa  TEXT,
  solicitado_em  TIMESTAMPTZ DEFAULT NOW(),
  respondido_em  TIMESTAMPTZ,
  created_at     TIMESTAMPTZ DEFAULT NOW(),
  updated_at     TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE (motoboy_id, restaurant_id)
);

CREATE INDEX IF NOT EXISTS idx_motoboy_estab_restaurant_status ON public.motoboy_estabelecimentos (restaurant_id, status);
CREATE INDEX IF NOT EXISTS idx_motoboy_estab_motoboy_status ON public.motoboy_estabelecimentos (motoboy_id, status);

ALTER TABLE public.motoboy_estabelecimentos ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'motoboy_estabelecimentos'
      AND policyname = 'motoboy_estabelecimentos_owner'
  ) THEN
    EXECUTE 'CREATE POLICY "motoboy_estabelecimentos_owner" ON public.motoboy_estabelecimentos
      FOR ALL USING (restaurant_id IN (SELECT id FROM public.restaurants WHERE user_id = auth.uid()))';
  END IF;
END $$;

-- Backfill: relações 1:1 existentes (motoboys.restaurant_id) viram afiliações já aceitas
INSERT INTO public.motoboy_estabelecimentos (motoboy_id, restaurant_id, status, solicitado_em, respondido_em)
SELECT id, restaurant_id, 'aceito', created_at, created_at
FROM public.motoboys
WHERE restaurant_id IS NOT NULL
ON CONFLICT (motoboy_id, restaurant_id) DO NOTHING;

