152	  private validarDadosMotoboy(
153	    body: MotoboyPeloRestauranteBody,
154	    opts: { exigirNome: boolean; exigirEmail: boolean; exigirSenha: boolean },
155	  ) {
156	    if (opts.exigirNome && !body.name?.trim()) throw new BadRequestException('Informe o nome do motoboy');
157	    if (opts.exigirEmail && !body.email) throw new BadRequestException('Informe o e-mail do motoboy');
158	    if (body.email && !EMAIL_RE.test(body.email)) throw new BadRequestException('E-mail inválido');
159	    if (body.phone && !PHONE_RE.test(body.phone)) throw new BadRequestException('Telefone inválido');
160	    if (opts.exigirSenha && (!body.password || body.password.length < 8)) {
161	      throw new BadRequestException('Senha deve ter no mínimo 8 caracteres');
162	    }
163	    if (!opts.exigirSenha && body.password && body.password.length < 8) {
164	      throw new BadRequestException('Senha deve ter no mínimo 8 caracteres');
165	    }
166	  }
