181	  async editarPeloRestaurante(motoboyId: number, restaurantId: number, body: MotoboyPeloRestauranteBody) {
182	    const mb = await this.exigirMotoboyGerenciadoPeloRestaurante(motoboyId, restaurantId);
183	    this.validarDadosMotoboy(body, { exigirNome: false, exigirEmail: false, exigirSenha: false });
184	
185	    // Senha/e-mail agora vivem no Supabase Auth — troca via admin API. Quando o
186	    // e-mail muda, o trigger sync_user_profile_email já mantém motoboys.email
187	    // sincronizado (dispara em AFTER UPDATE OF email ON auth.users).
188	    if (mb.user_id && (body.password || (body.email && body.email !== mb.email))) {
189	      const payload: Record<string, any> = {};
190	      if (body.password) payload.password = body.password;
191	      if (body.email && body.email !== mb.email) {
192	        payload.email = body.email;
193	        payload.email_confirm = true;
194	      }
195	      const { error: authError } = await this.supabase.client.auth.admin.updateUserById(mb.user_id, payload);
196	      if (authError) throw authError;
197	    }
198	
199	    const campos: Record<string, any> = {};
200	    if (body.name !== undefined) campos.name = body.name.trim();
201	    if (body.phone !== undefined) campos.phone = body.phone || null;
202	    // E-mail só é escrito aqui se o motoboy não tem user_id (nunca migrou pro
203	    // Supabase Auth) — senão o trigger acima já cuida disso.
204	    if (!mb.user_id && body.email !== undefined) campos.email = body.email || null;
205	    if (Object.keys(campos).length === 0) return { ok: true };
206	
207	    const { error } = await this.supabase.client.from('motoboys').update(campos).eq('id', motoboyId);
208	    if (error) throw error;
209	    return { ok: true };
210	  }
