492	        'id, total, troco_para, status, payment_method, restaurant_id, created_at, updated_at, motoboy_lat, motoboy_lng, customer_id, delivery_notes, delivery_occurrence, pago_em, frete_cobrado, frete_excedente_cobrado, distancia_entrega_km',
