505	        r.id,
506	        { name: r.name, chave_pix: r.payment_config?.chave_pix ?? null, taxa_cartao_percentual: r.taxa_cartao_percentual ?? 0 },
507	      ]),
508	    );
509	
510	    const pedidos = await Promise.all(
511	      (data ?? []).map(async (p) => {
512	        const [{ data: c }, { data: itensRaw }] = await Promise.all([
513	          p.customer_id
514	            ? this.supabase.client
515	                .from('customers')
516	                .select('name, phone_e164, address_json')
517	                .eq('id', p.customer_id)
518	                .maybeSingle()
519	            : Promise.resolve({ data: null }),
520	          this.supabase.client
521	            .from('order_items')
522	            .select('id, quantity, unit_price, product_id')
523	            .eq('order_id', p.id),
524	        ]);
525	
526	        let itens = itensRaw ?? [];
527	        if (itens.length > 0) {
528	          const prodIds = itens.map((i: any) => i.product_id);
529	          const { data: prods } = await this.supabase.client
530	            .from('products')
531	            .select('id, name')
532	            .in('id', prodIds);
533	          const prodMap = Object.fromEntries((prods ?? []).map((pr: any) => [pr.id, pr.name]));
534	          itens = itens.map((i: any) => ({ ...i, product_name: prodMap[i.product_id] ?? `Produto #${i.product_id}` }));
535	        }
536	
537	        return { ...p, cliente: c, itens, restaurante: restMap[p.restaurant_id] ?? null };
538	      }),
539	    );
540	    return { pedidos };
541	  }
