553	  async confirmarEntrega(
554	    pedidoId: number,
555	    motoboyId: number,
556	    entregaPagamento?: { metodo: string; dinheiro?: number; pix?: number; cartao?: number },
557	  ) {
558	    const { data: pedido } = await this.supabase.client
559	      .from('orders')
560	      .select('id, status, restaurant_id, total, frete_cobrado, frete_excedente_cobrado, distancia_entrega_km, customer_id, payment_method')
561	      .eq('id', pedidoId)
562	      .eq('motoboy_id', motoboyId)
563	      .maybeSingle();
564	    if (!pedido) throw new NotFoundException('Pedido não encontrado ou não atribuído a você');
565	
566	    // Pagamento combinado (dinheiro + PIX + cartão em qualquer fração) — a soma das
567	    // frações precisa bater com o total do pedido, senão dinheiro "some"/"aparece"
568	    // do nada no caixa. Os outros métodos (exato/pix/cartao) já mandam o valor certo
569	    // num campo só, exceto "conforme" com troco, que intencionalmente manda mais que
570	    // o total (é o que o cliente entregou em mãos, não o valor da venda).
571	    if (entregaPagamento?.metodo === 'combinado') {
572	      const soma = (entregaPagamento.dinheiro ?? 0) + (entregaPagamento.pix ?? 0) + (entregaPagamento.cartao ?? 0);
573	      if (Math.abs(soma - pedido.total) > 0.01) {
574	        throw new BadRequestException('Soma dos valores não bate com o total do pedido');
575	      }
576	    }
577	
578	    // Taxa do cartão é sempre recalculada no backend (não confia no valor vindo do
579	    // app) — mesma fórmula/config do módulo Salão (Config > "Taxa do cartão"). Incide
580	    // só sobre a fatia paga no cartão, não sobre o pedido inteiro — importante no
581	    // pagamento combinado, onde o cartão pode ser só parte do total.
582	    let taxaCartaoValor = 0;
583	    if ((entregaPagamento?.cartao ?? 0) > 0) {
584	      taxaCartaoValor = await this.salaoService.calcularTaxaCartao(pedido.restaurant_id, entregaPagamento!.cartao!, 'credit_card');
585	      entregaPagamento = { ...entregaPagamento, taxa_cartao_valor: taxaCartaoValor } as any;
586	    }
587	
588	    const updatePayload: Record<string, any> = { status: 'delivered', updated_at: new Date().toISOString() };
589	    if (entregaPagamento) {
590	      updatePayload.entrega_pagamento = entregaPagamento;
591	      updatePayload.pago_em = new Date().toISOString();
592	    }
593	
594	    const { error } = await this.supabase.client
595	      .from('orders')
596	      .update(updatePayload)
597	      .eq('id', pedidoId);
598	    if (error) throw error;
599	
600	    // Registrar entrada(s) no caixa aberto
601	    if (entregaPagamento && pedido.restaurant_id) {
602	      const { data: caixa } = await this.supabase.client
603	        .from('caixas')
604	        .select('id, entradas')
605	        .eq('restaurant_id', pedido.restaurant_id)
606	        .eq('status', 'aberto')
607	        .maybeSingle();
608	
609	      if (caixa) {
610	        const entradas = (caixa.entradas ?? []) as any[];
