1025	  async ganhosResumo(motoboyId: number) {
1026	    const { data, error } = await this.supabase.client
1027	      .from('motoboy_comissoes')
1028	      .select('restaurant_id, comissao_valor, criado_em, restaurant:restaurants(name)')
1029	      .eq('motoboy_id', motoboyId);
1030	    if (error) throw error;
1031	
1032	    const porRestaurante = new Map<number, { restaurant_id: number; nome: string; total: number; entregas: number }>();
1033	    for (const row of data ?? []) {
1034	      const atual = porRestaurante.get(row.restaurant_id) ?? {
1035	        restaurant_id: row.restaurant_id,
1036	        nome: (row as any).restaurant?.name ?? `Estabelecimento #${row.restaurant_id}`,
1037	        total: 0,
1038	        entregas: 0,
1039	      };
1040	      atual.total += Number(row.comissao_valor);
1041	      atual.entregas += 1;
1042	      porRestaurante.set(row.restaurant_id, atual);
1043	    }
1044	
1045	    const resumo = [...porRestaurante.values()].sort((a, b) => b.total - a.total);
1046	    const totalGeral = resumo.reduce((acc, r) => acc + r.total, 0);
1047	
1048	    // "Hoje" pra aba Financeiro do motoboy acompanhar a produção do dia — mesmo corte de
1049	    // data (início do dia local) usado em relatorioFretes.
1050	    const inicioHoje = new Date();
1051	    inicioHoje.setHours(0, 0, 0, 0);
1052	    const hojeRows = (data ?? []).filter((row: any) => new Date(row.criado_em) >= inicioHoje);
1053	    const hoje = {
1054	      entregas: hojeRows.length,
1055	      total: hojeRows.reduce((acc: number, r: any) => acc + Number(r.comissao_valor), 0),
1056	    };
1057	
1058	    return { resumo, total_geral: totalGeral, hoje };
1059	  }
1060	
1061	  // Produção por dia pra aba Financeiro do motoboy — mesmo padrão de agrupamento por dia
1062	  // usado em relatorioFretes (por_dia). Sem de/ate (uso original, antes do filtro de
1063	  // período), cai no default de últimos 14 dias.
1064	  async ganhosPorDia(motoboyId: number, restaurantId?: number, de?: string, ate?: string) {
1065	    let query = this.supabase.client
1066	      .from('motoboy_comissoes')
1067	      .select('comissao_valor, criado_em')
1068	      .eq('motoboy_id', motoboyId);
1069	
1070	    if (de && ate) {
1071	      query = query.gte('criado_em', de).lte('criado_em', ate);
1072	    } else {
1073	      const cutoff = new Date();
1074	      cutoff.setDate(cutoff.getDate() - 14);
1075	      cutoff.setHours(0, 0, 0, 0);
1076	      query = query.gte('criado_em', cutoff.toISOString());
1077	    }
1078	    if (restaurantId) query = query.eq('restaurant_id', restaurantId);
1079	
1080	    const { data, error } = await query;
1081	    if (error) throw error;
1082	
1083	    const porDia: Record<string, { dia: string; data: string; entregas: number; total: number }> = {};
1084	    for (const row of (data ?? []) as any[]) {
1085	      const d = new Date(row.criado_em);
1086	      const chave = d.toISOString().slice(0, 10);
