import { BadRequestException, ConflictException, ForbiddenException, Injectable, NotFoundException } from '@nestjs/common';
import { SupabaseService } from '../supabase/supabase.service';
import { ComissaoService } from './comissao.service';
import { GeocodingService } from './geocoding.service';
import { EstoqueService } from '../estoque/estoque.service';
import { SalaoService } from '../salao/salao.service';
import { EMAIL_RE, PHONE_RE } from './motoboy-auth.service';

export interface MotoboyPeloRestauranteBody {
  name?: string;
  phone?: string;
  email?: string;
  password?: string;
}

const DOC_BUCKET = 'motoboy-documentos';
const SIGNED_URL_TTL = 60 * 10; // 10 min

@Injectable()
export class MotoboyService {
  constructor(
    private supabase: SupabaseService,
    private comissao: ComissaoService,
    private geocoding: GeocodingService,
    private estoque: EstoqueService,
    private salaoService: SalaoService,
  ) {}

  // Antes de ver/solicitar vaga em qualquer estabelecimento, a plataforma
  // (admin) precisa ter revisado e aprovado o cadastro do motoboy.
  private async exigirAprovacaoPlataforma(motoboyId: number) {
    const { data } = await this.supabase.client
      .from('motoboys')
      .select('status_plataforma')
      .eq('id', motoboyId)
      .maybeSingle();
    if (data?.status_plataforma !== 'aprovado') {
      throw new ForbiddenException('Seu cadastro ainda está em análise pela plataforma. Aguarde a aprovação pra ver os estabelecimentos.');
    }
  }

  private async exigirAfiliacaoAceita(motoboyId: number, restaurantId: number) {
    const { data } = await this.supabase.client
      .from('motoboy_estabelecimentos')
      .select('id, bloqueado')
      .eq('motoboy_id', motoboyId)
      .eq('restaurant_id', restaurantId)
      .eq('status', 'aceito')
      .maybeSingle();
    if (!data) throw new ForbiddenException('Motoboy não está afiliado a este estabelecimento');
    if (data.bloqueado) throw new ForbiddenException('Motoboy está bloqueado neste estabelecimento');
  }

  // Estabelecimento que optou por entregar por conta própria não deve aparecer
  // pra motoboys pegarem pedido sozinhos — o dono ainda pode atribuir manualmente
  // como exceção (não passa por aqui).
  private async exigirUsaMotoboy(restaurantId: number) {
    const { data } = await this.supabase.client
      .from('restaurants')
      .select('usa_motoboy')
      .eq('id', restaurantId)
      .maybeSingle();
    if (data && data.usa_motoboy === false) {
      throw new ForbiddenException('Este estabelecimento faz entregas por conta própria');
    }
  }

  private async signedUrl(path: string | null | undefined): Promise<string | null> {
    if (!path) return null;
    const { data } = await this.supabase.client.storage.from(DOC_BUCKET).createSignedUrl(path, SIGNED_URL_TTL);
    return data?.signedUrl ?? null;
  }

  // ── Lado restaurante: gestão de afiliados ──────────────────────────

  async listar(restaurantId: number) {
    const { data, error } = await this.supabase.client
      .from('motoboy_estabelecimentos')
      .select('bloqueado, motoboy:motoboys(id, name, phone, foto_perfil_url, criado_por_restaurant_id)')
      .eq('restaurant_id', restaurantId)
      .eq('status', 'aceito');
    if (error) throw error;

    const motoboys = await Promise.all(
      (data ?? []).map(async (row: any) => {
        const resto = row.motoboy ?? {};
        return {
          ...resto,
          foto_perfil_url: await this.signedUrl(resto.foto_perfil_url),
          bloqueado: row.bloqueado,
          gerenciado_por_mim: resto.criado_por_restaurant_id === restaurantId,
        };
      }),
    );
    return { motoboys };
  }

  // Cadastro direto: o próprio estabelecimento registra um motoboy seu, sem
  // passar pelo autocadastro do app + aprovação da plataforma + solicitação de
  // afiliação — já nasce aprovado e afiliado (o restaurante está vouching por ele).
  // Cria uma conta Supabase Auth de verdade (não mais password_hash local) —
  // e-mail é obrigatório porque é a identidade de login.
  async criarPeloRestaurante(restaurantId: number, body: MotoboyPeloRestauranteBody) {
    this.validarDadosMotoboy(body, { exigirNome: true, exigirEmail: true, exigirSenha: true });

    const { data: existente } = await this.supabase.client
      .from('motoboys')
      .select('id')
      .or(`email.eq.${body.email ?? ''},phone.eq.${body.phone ?? ''}`)
      .maybeSingle();
    if (existente) throw new ConflictException('Já existe um cadastro de motoboy com este telefone ou e-mail');

    const { data: criado, error: authError } = await this.supabase.client.auth.admin.createUser({
      email: body.email,
      password: body.password,
      email_confirm: true,
      user_metadata: { name: body.name, role: 'motoboy' },
    });
    if (authError) {
      if (authError.status === 422 || authError.message?.toLowerCase().includes('already')) {
        throw new ConflictException('Já existe uma conta com este e-mail');
      }
      throw authError;
    }

    const agora = new Date().toISOString();

    const { data: motoboy, error } = await this.supabase.client
      .from('motoboys')
      .insert({
        user_id: criado.user.id,
        name: body.name!.trim(),
        phone: body.phone || null,
        email: body.email,
        precisa_completar_cadastro: false,
        status_plataforma: 'aprovado',
        aprovado_em: agora,
        criado_por_restaurant_id: restaurantId,
      })
      .select('id, name, phone, email')
      .single();
    if (error) throw error;

    const { error: afilError } = await this.supabase.client
      .from('motoboy_estabelecimentos')
      .insert({ motoboy_id: motoboy.id, restaurant_id: restaurantId, status: 'aceito', solicitado_em: agora, respondido_em: agora });
    if (afilError) throw afilError;

    return { ...motoboy, criado_por_restaurant_id: restaurantId, bloqueado: false, sessao_ativa: false, gerenciado_por_mim: true };
  }

  private validarDadosMotoboy(
    body: MotoboyPeloRestauranteBody,
    opts: { exigirNome: boolean; exigirEmail: boolean; exigirSenha: boolean },
  ) {
    if (opts.exigirNome && !body.name?.trim()) throw new BadRequestException('Informe o nome do motoboy');
    if (opts.exigirEmail && !body.email) throw new BadRequestException('Informe o e-mail do motoboy');
    if (body.email && !EMAIL_RE.test(body.email)) throw new BadRequestException('E-mail inválido');
    if (body.phone && !PHONE_RE.test(body.phone)) throw new BadRequestException('Telefone inválido');
    if (opts.exigirSenha && (!body.password || body.password.length < 8)) {
      throw new BadRequestException('Senha deve ter no mínimo 8 caracteres');
    }
    if (!opts.exigirSenha && body.password && body.password.length < 8) {
      throw new BadRequestException('Senha deve ter no mínimo 8 caracteres');
    }
  }

  private async exigirMotoboyGerenciadoPeloRestaurante(motoboyId: number, restaurantId: number) {
    const { data: mb } = await this.supabase.client
      .from('motoboys')
      .select('id, user_id, email, criado_por_restaurant_id')
      .eq('id', motoboyId)
      .maybeSingle();
    if (!mb) throw new NotFoundException('Motoboy não encontrado');
    if (mb.criado_por_restaurant_id !== restaurantId) {
      throw new ForbiddenException('Essa ação só é permitida em motoboys cadastrados diretamente por este estabelecimento');
    }
    return mb;
  }

  async editarPeloRestaurante(motoboyId: number, restaurantId: number, body: MotoboyPeloRestauranteBody) {
    const mb = await this.exigirMotoboyGerenciadoPeloRestaurante(motoboyId, restaurantId);
    this.validarDadosMotoboy(body, { exigirNome: false, exigirEmail: false, exigirSenha: false });

    // Senha/e-mail agora vivem no Supabase Auth — troca via admin API. Quando o
    // e-mail muda, o trigger sync_user_profile_email já mantém motoboys.email
    // sincronizado (dispara em AFTER UPDATE OF email ON auth.users).
    if (mb.user_id && (body.password || (body.email && body.email !== mb.email))) {
      const payload: Record<string, any> = {};
      if (body.password) payload.password = body.password;
      if (body.email && body.email !== mb.email) {
        payload.email = body.email;
        payload.email_confirm = true;
      }
      const { error: authError } = await this.supabase.client.auth.admin.updateUserById(mb.user_id, payload);
      if (authError) throw authError;
    }

    const campos: Record<string, any> = {};
    if (body.name !== undefined) campos.name = body.name.trim();
    if (body.phone !== undefined) campos.phone = body.phone || null;
    // E-mail só é escrito aqui se o motoboy não tem user_id (nunca migrou pro
    // Supabase Auth) — senão o trigger acima já cuida disso.
    if (!mb.user_id && body.email !== undefined) campos.email = body.email || null;
    if (Object.keys(campos).length === 0) return { ok: true };

    const { error } = await this.supabase.client.from('motoboys').update(campos).eq('id', motoboyId);
    if (error) throw error;
    return { ok: true };
  }

  // Link de definir/redefinir senha (pra copiar/mandar por WhatsApp) — gerado
  // via Admin API, não depende do envio de e-mail do Supabase.
  async gerarLinkRedefinicaoSenha(motoboyId: number, restaurantId: number, redirectTo?: string) {
    const mb = await this.exigirMotoboyGerenciadoPeloRestaurante(motoboyId, restaurantId);
    if (!mb.user_id) throw new NotFoundException('Este motoboy ainda não tem conta migrada — edite e informe um e-mail primeiro.');

    const { data, error } = await this.supabase.client.auth.admin.generateLink({
      type: 'recovery',
      email: mb.email,
      options: redirectTo ? { redirectTo } : undefined,
    });
    if (error) throw error;
    return { link: data.properties.action_link };
  }

  // Mesmo mecanismo que o cliente já usa em "esqueci minha senha" — sem mailer
  // próprio, reaproveita o e-mail nativo do Supabase Auth.
  async enviarLinkRedefinicaoSenhaPorEmail(motoboyId: number, restaurantId: number, redirectTo?: string) {
    const mb = await this.exigirMotoboyGerenciadoPeloRestaurante(motoboyId, restaurantId);
    if (!mb.user_id) throw new NotFoundException('Este motoboy ainda não tem conta migrada — edite e informe um e-mail primeiro.');

    const { error } = await this.supabase.client.auth.resetPasswordForEmail(mb.email, redirectTo ? { redirectTo } : undefined);
    if (error) throw error;
    return { ok: true };
  }

  // Excluir de verdade só é seguro sem histórico de entregas (motoboy_comissoes
  // referencia motoboy_id com ON DELETE CASCADE — apagaria ganhos já registrados).
  // Com histórico, orientar a bloquear em vez de excluir.
  async excluirPeloRestaurante(motoboyId: number, restaurantId: number) {
    await this.exigirMotoboyGerenciadoPeloRestaurante(motoboyId, restaurantId);

    const { count } = await this.supabase.client
      .from('motoboy_comissoes')
      .select('id', { count: 'exact', head: true })
      .eq('motoboy_id', motoboyId);
    if ((count ?? 0) > 0) {
      throw new BadRequestException('Este motoboy já tem entregas registradas — bloqueie em vez de excluir, pra não perder o histórico.');
    }

    const { error } = await this.supabase.client.from('motoboys').delete().eq('id', motoboyId);
    if (error) throw error;
    return { ok: true };
  }

  // Pausa o motoboy pra este restaurante (não pega/recebe pedidos daqui) sem
  // desfazer a afiliação — diferente de removerAfiliacao, que exige nova solicitação.
  async bloquearAfiliacao(motoboyId: number, restaurantId: number, bloqueado: boolean) {
    const { data, error } = await this.supabase.client
      .from('motoboy_estabelecimentos')
      .update({ bloqueado, updated_at: new Date().toISOString() })
      .eq('motoboy_id', motoboyId)
      .eq('restaurant_id', restaurantId)
      .eq('status', 'aceito')
      .select()
      .maybeSingle();
    if (error) throw error;
    if (!data) throw new NotFoundException('Afiliação não encontrada');
    return { ok: true, bloqueado };
  }

  async listarSolicitacoes(restaurantId: number, status: 'pendente' | 'aceito' | 'recusado' = 'pendente') {
    // Pra pendente precisamos da ficha completa (docs via signed URL); pra histórico
    // (aceito/recusado) só o básico, evita gerar signed URL à toa por linha.
    const campos = status === 'pendente'
      ? 'motoboy:motoboys(id, name, phone, email, foto_perfil_url, documento_frente_url, documento_verso_url, comprovante_endereco_url)'
      : 'motoboy:motoboys(id, name, phone, email)';

    const { data, error } = await this.supabase.client
      .from('motoboy_estabelecimentos')
      .select(`id, solicitado_em, respondido_em, motivo_recusa, ${campos}`)
      .eq('restaurant_id', restaurantId)
      .eq('status', status)
      .order(status === 'pendente' ? 'solicitado_em' : 'respondido_em', { ascending: status === 'pendente' });
    if (error) throw error;

    if (status !== 'pendente') {
      return {
        solicitacoes: (data ?? []).map((row: any) => ({
          id: row.id,
          solicitado_em: row.solicitado_em,
          respondido_em: row.respondido_em,
          motivo_recusa: row.motivo_recusa,
          motoboy: row.motoboy,
        })),
      };
    }

    const solicitacoes = await Promise.all(
      (data ?? []).map(async (row: any) => ({
        id: row.id,
        solicitado_em: row.solicitado_em,
        motoboy: {
          ...row.motoboy,
          foto_perfil_url: await this.signedUrl(row.motoboy?.foto_perfil_url),
          documento_frente_url: await this.signedUrl(row.motoboy?.documento_frente_url),
          documento_verso_url: await this.signedUrl(row.motoboy?.documento_verso_url),
          comprovante_endereco_url: await this.signedUrl(row.motoboy?.comprovante_endereco_url),
        },
      })),
    );
    return { solicitacoes };
  }

  async contarSolicitacoesPendentes(restaurantId: number) {
    const { count, error } = await this.supabase.client
      .from('motoboy_estabelecimentos')
      .select('id', { count: 'exact', head: true })
      .eq('restaurant_id', restaurantId)
      .eq('status', 'pendente');
    if (error) throw error;
    return { count: count ?? 0 };
  }

  async aceitarSolicitacao(id: number, restaurantId: number) {
    const { data, error } = await this.supabase.client
      .from('motoboy_estabelecimentos')
      .update({ status: 'aceito', respondido_em: new Date().toISOString(), updated_at: new Date().toISOString() })
      .eq('id', id)
      .eq('restaurant_id', restaurantId)
      .eq('status', 'pendente')
      .select()
      .maybeSingle();
    if (error) throw error;
    if (!data) throw new NotFoundException('Solicitação não encontrada ou já respondida');
    return data;
  }

  async recusarSolicitacao(id: number, restaurantId: number, motivo?: string) {
    const { data, error } = await this.supabase.client
      .from('motoboy_estabelecimentos')
      .update({
        status: 'recusado',
        motivo_recusa: motivo ?? null,
        respondido_em: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .eq('id', id)
      .eq('restaurant_id', restaurantId)
      .eq('status', 'pendente')
      .select()
      .maybeSingle();
    if (error) throw error;
    if (!data) throw new NotFoundException('Solicitação não encontrada ou já respondida');
    return data;
  }

  // Restaurante muda de ideia sobre uma solicitação recusada — volta pra "pendente"
  // pra reavaliar (limpa motivo/data da recusa anterior).
  async revisarSolicitacao(id: number, restaurantId: number) {
    const { data, error } = await this.supabase.client
      .from('motoboy_estabelecimentos')
      .update({
        status: 'pendente',
        motivo_recusa: null,
        respondido_em: null,
        updated_at: new Date().toISOString(),
      })
      .eq('id', id)
      .eq('restaurant_id', restaurantId)
      .eq('status', 'recusado')
      .select()
      .maybeSingle();
    if (error) throw error;
    if (!data) throw new NotFoundException('Solicitação recusada não encontrada');
    return data;
  }

  async removerAfiliacao(motoboyId: number, restaurantId: number) {
    const { data, error } = await this.supabase.client
      .from('motoboy_estabelecimentos')
      .update({ status: 'removido', updated_at: new Date().toISOString() })
      .eq('motoboy_id', motoboyId)
      .eq('restaurant_id', restaurantId)
      .eq('status', 'aceito')
      .select()
      .maybeSingle();
    if (error) throw error;
    if (!data) throw new NotFoundException('Afiliação não encontrada');
    return { ok: true };
  }

  async atribuir(pedidoId: number, restaurantId: number, motoboyId: number) {
    await this.exigirAfiliacaoAceita(motoboyId, restaurantId);

    const { error } = await this.supabase.client
      .from('orders')
      .update({ motoboy_id: motoboyId, status: 'out_for_delivery', updated_at: new Date().toISOString() })
      .eq('id', pedidoId)
      .eq('restaurant_id', restaurantId);
    if (error) throw error;
    return { ok: true, status: 'out_for_delivery' };
  }

  // ── Lado motoboy: buscar/solicitar afiliação ───────────────────────

  async buscarEstabelecimentos(motoboyId: number, busca?: string) {
    await this.exigirAprovacaoPlataforma(motoboyId);

    let query = this.supabase.client
      .from('restaurants')
      .select('id, name, address, logo_url')
      .eq('bloqueado', false)
      .order('name')
      .limit(50);
    if (busca) query = query.ilike('name', `%${busca}%`);
    const { data: restaurantes, error } = await query;
    if (error) throw error;

    const ids = (restaurantes ?? []).map((r) => r.id);
    const { data: afiliacoes } = ids.length
      ? await this.supabase.client
          .from('motoboy_estabelecimentos')
          .select('restaurant_id, status')
          .eq('motoboy_id', motoboyId)
          .in('restaurant_id', ids)
      : { data: [] as any[] };
    const statusMap = Object.fromEntries((afiliacoes ?? []).map((a: any) => [a.restaurant_id, a.status]));

    return {
      estabelecimentos: (restaurantes ?? []).map((r) => ({ ...r, status_afiliacao: statusMap[r.id] ?? null })),
    };
  }

  async solicitarAfiliacao(motoboyId: number, restaurantId: number) {
    await this.exigirAprovacaoPlataforma(motoboyId);

    const { data: existente } = await this.supabase.client
      .from('motoboy_estabelecimentos')
      .select('id, status')
      .eq('motoboy_id', motoboyId)
      .eq('restaurant_id', restaurantId)
      .maybeSingle();

    if (existente) {
      if (existente.status === 'aceito') throw new ConflictException('Você já atende este estabelecimento');
      if (existente.status === 'pendente') throw new ConflictException('Solicitação já enviada, aguardando resposta');
      // recusado ou removido — reabre como pendente
      const { data, error } = await this.supabase.client
        .from('motoboy_estabelecimentos')
        .update({
          status: 'pendente',
          motivo_recusa: null,
          solicitado_em: new Date().toISOString(),
          respondido_em: null,
          updated_at: new Date().toISOString(),
        })
        .eq('id', existente.id)
        .select()
        .single();
      if (error) throw error;
      return data;
    }

    const { data, error } = await this.supabase.client
      .from('motoboy_estabelecimentos')
      .insert({ motoboy_id: motoboyId, restaurant_id: restaurantId })
      .select()
      .single();
    if (error) throw error;
    return data;
  }

  async minhasAfiliacoes(motoboyId: number) {
    const { data, error } = await this.supabase.client
      .from('motoboy_estabelecimentos')
      .select('id, status, motivo_recusa, solicitado_em, respondido_em, restaurant:restaurants(id, name, address, logo_url)')
      .eq('motoboy_id', motoboyId)
      .neq('status', 'removido')
      .order('solicitado_em', { ascending: false });
    if (error) throw error;
    return { afiliacoes: data ?? [] };
  }

  // ── Motoboy portal: pedidos ─────────────────────────────────────────

  async meusPedidos(motoboyId: number) {
    const { data, error } = await this.supabase.client
      .from('orders')
      .select(
        'id, total, troco_para, status, payment_method, restaurant_id, created_at, updated_at, motoboy_lat, motoboy_lng, customer_id, delivery_notes, delivery_occurrence, pago_em, frete_cobrado, frete_excedente_cobrado, distancia_entrega_km',
      )
      .eq('motoboy_id', motoboyId)
      .not('status', 'in', '("delivered","canceled")')
      .order('created_at', { ascending: false });
    if (error) throw error;

    const restIds = [...new Set((data ?? []).map((p) => p.restaurant_id).filter(Boolean))];
    const { data: restaurantes } = restIds.length
      ? await this.supabase.client.from('restaurants').select('id, name, payment_config, taxa_cartao_percentual').in('id', restIds)
      : { data: [] as any[] };
    const restMap = Object.fromEntries(
      (restaurantes ?? []).map((r: any) => [
        r.id,
        { name: r.name, chave_pix: r.payment_config?.chave_pix ?? null, taxa_cartao_percentual: r.taxa_cartao_percentual ?? 0 },
      ]),
    );

    const pedidos = await Promise.all(
      (data ?? []).map(async (p) => {
        const [{ data: c }, { data: itensRaw }] = await Promise.all([
          p.customer_id
            ? this.supabase.client
                .from('customers')
                .select('name, phone_e164, address_json')
                .eq('id', p.customer_id)
                .maybeSingle()
            : Promise.resolve({ data: null }),
          this.supabase.client
            .from('order_items')
            .select('id, quantity, unit_price, product_id')
            .eq('order_id', p.id),
        ]);

        let itens = itensRaw ?? [];
        if (itens.length > 0) {
          const prodIds = itens.map((i: any) => i.product_id);
          const { data: prods } = await this.supabase.client
            .from('products')
            .select('id, name')
            .in('id', prodIds);
          const prodMap = Object.fromEntries((prods ?? []).map((pr: any) => [pr.id, pr.name]));
          itens = itens.map((i: any) => ({ ...i, product_name: prodMap[i.product_id] ?? `Produto #${i.product_id}` }));
        }

        return { ...p, cliente: c, itens, restaurante: restMap[p.restaurant_id] ?? null };
      }),
    );
    return { pedidos };
  }

  async atualizarLocalizacao(pedidoId: number, motoboyId: number, lat: number, lng: number) {
    const { error } = await this.supabase.client
      .from('orders')
      .update({ motoboy_lat: lat, motoboy_lng: lng, motoboy_location_at: new Date().toISOString() })
      .eq('id', pedidoId)
      .eq('motoboy_id', motoboyId);
    if (error) throw error;
    return { ok: true };
  }

  async confirmarEntrega(
    pedidoId: number,
    motoboyId: number,
    entregaPagamento?: { metodo: string; dinheiro?: number; pix?: number; cartao?: number },
  ) {
    const { data: pedido } = await this.supabase.client
      .from('orders')
      .select('id, status, restaurant_id, total, frete_cobrado, frete_excedente_cobrado, distancia_entrega_km, customer_id, payment_method')
      .eq('id', pedidoId)
      .eq('motoboy_id', motoboyId)
      .maybeSingle();
    if (!pedido) throw new NotFoundException('Pedido não encontrado ou não atribuído a você');

    // Pagamento combinado (dinheiro + PIX + cartão em qualquer fração) — a soma das
    // frações precisa bater com o total do pedido, senão dinheiro "some"/"aparece"
    // do nada no caixa. Os outros métodos (exato/pix/cartao) já mandam o valor certo
    // num campo só, exceto "conforme" com troco, que intencionalmente manda mais que
    // o total (é o que o cliente entregou em mãos, não o valor da venda).
    if (entregaPagamento?.metodo === 'combinado') {
      const soma = (entregaPagamento.dinheiro ?? 0) + (entregaPagamento.pix ?? 0) + (entregaPagamento.cartao ?? 0);
      if (Math.abs(soma - pedido.total) > 0.01) {
        throw new BadRequestException('Soma dos valores não bate com o total do pedido');
      }
    }

    // Taxa do cartão é sempre recalculada no backend (não confia no valor vindo do
    // app) — mesma fórmula/config do módulo Salão (Config > "Taxa do cartão"). Incide
    // só sobre a fatia paga no cartão, não sobre o pedido inteiro — importante no
    // pagamento combinado, onde o cartão pode ser só parte do total.
    let taxaCartaoValor = 0;
    if ((entregaPagamento?.cartao ?? 0) > 0) {
      taxaCartaoValor = await this.salaoService.calcularTaxaCartao(pedido.restaurant_id, entregaPagamento!.cartao!, 'credit_card');
      entregaPagamento = { ...entregaPagamento, taxa_cartao_valor: taxaCartaoValor } as any;
    }

    const updatePayload: Record<string, any> = { status: 'delivered', updated_at: new Date().toISOString() };
    if (entregaPagamento) {
      updatePayload.entrega_pagamento = entregaPagamento;
      updatePayload.pago_em = new Date().toISOString();
    }

    const { error } = await this.supabase.client
      .from('orders')
      .update(updatePayload)
      .eq('id', pedidoId);
    if (error) throw error;

    // Registrar entrada(s) no caixa aberto
    if (entregaPagamento && pedido.restaurant_id) {
      const { data: caixa } = await this.supabase.client
        .from('caixas')
        .select('id, entradas')
        .eq('restaurant_id', pedido.restaurant_id)
        .eq('status', 'aberto')
        .maybeSingle();

      if (caixa) {
        const entradas = (caixa.entradas ?? []) as any[];
        const novas: any[] = [];
        const agora = new Date().toISOString();

        if ((entregaPagamento.dinheiro ?? 0) > 0) {
          novas.push({
            descricao: `Entrega pedido #${pedidoId} — dinheiro`,
            valor: entregaPagamento.dinheiro,
            meio: 'dinheiro',
            criado_em: agora,
          });
        }
        if ((entregaPagamento.pix ?? 0) > 0) {
          novas.push({
            descricao: `Entrega pedido #${pedidoId} — PIX`,
            valor: entregaPagamento.pix,
            meio: 'pix',
            criado_em: agora,
          });
        }
        if ((entregaPagamento.cartao ?? 0) > 0) {
          novas.push({
            descricao: `Entrega pedido #${pedidoId} — Cartão${taxaCartaoValor > 0 ? ` (+ taxa ${taxaCartaoValor})` : ''}`,
            valor: (entregaPagamento.cartao ?? 0) + taxaCartaoValor,
            meio: 'cartao',
            criado_em: agora,
          });
        }

        if (novas.length > 0) {
          await this.supabase.client
            .from('caixas')
            .update({ entradas: [...entradas, ...novas] })
            .eq('id', caixa.id);
        }
      }
    }

    // Pedido já veio com "pagamento em dinheiro" escolhido no checkout (não é o motoboy
    // reportando o que cobrou na hora — isso é o `entregaPagamento` acima) — sem isso o
    // caixa físico nunca credita essa venda, só o fundo inicial (mesmo bug do salão).
    if (!entregaPagamento?.dinheiro && pedido.payment_method === 'cash' && pedido.restaurant_id) {
      await this.salaoService.registrarEntradaCaixa(pedido.restaurant_id, `Venda delivery em dinheiro - Pedido #${pedidoId}`, pedido.total, 'venda_dinheiro');
    }

    // Calcula e registra a comissão do motoboy (idempotente — UNIQUE(pedido_id))
    await this.comissao.registrarComissaoEntrega(pedido, motoboyId);

    return { ok: true, pedido_id: pedidoId, status: 'delivered' };
  }

  // Dono do restaurante marca um pedido como entregue pela própria loja, sem motoboy.
  // Só permitido se não houver motoboy atribuído (evita marcar como entrega própria
  // um pedido que já está com um motoboy de verdade).
  async entregarProprio(
    pedidoId: number,
    restaurantId: number,
    entregaPagamento?: { metodo: string; dinheiro?: number; pix?: number },
  ) {
    const { data: pedido } = await this.supabase.client
      .from('orders')
      .select('id, status, restaurant_id, motoboy_id, total, payment_method')
      .eq('id', pedidoId)
      .eq('restaurant_id', restaurantId)
      .maybeSingle();
    if (!pedido) throw new NotFoundException('Pedido não encontrado neste restaurante');
    if (pedido.motoboy_id) throw new BadRequestException('Pedido já está atribuído a um motoboy');

    const updatePayload: Record<string, any> = {
      status: 'delivered',
      entrega_propria: true,
      updated_at: new Date().toISOString(),
    };
    if (entregaPagamento) updatePayload.entrega_pagamento = entregaPagamento;

    const { error } = await this.supabase.client.from('orders').update(updatePayload).eq('id', pedidoId);
    if (error) throw error;

    if (entregaPagamento) {
      const { data: caixa } = await this.supabase.client
        .from('caixas')
        .select('id, entradas')
        .eq('restaurant_id', restaurantId)
        .eq('status', 'aberto')
        .maybeSingle();

      if (caixa) {
        const entradas = (caixa.entradas ?? []) as any[];
        const novas: any[] = [];
        const agora = new Date().toISOString();

        if ((entregaPagamento.dinheiro ?? 0) > 0) {
          novas.push({
            descricao: `Entrega própria pedido #${pedidoId} — dinheiro`,
            valor: entregaPagamento.dinheiro,
            meio: 'dinheiro',
            criado_em: agora,
          });
        }
        if ((entregaPagamento.pix ?? 0) > 0) {
          novas.push({
            descricao: `Entrega própria pedido #${pedidoId} — PIX`,
            valor: entregaPagamento.pix,
            meio: 'pix',
            criado_em: agora,
          });
        }

        if (novas.length > 0) {
          await this.supabase.client.from('caixas').update({ entradas: [...entradas, ...novas] }).eq('id', caixa.id);
        }
      }
    }

    // Idem confirmarEntrega: pedido pago em dinheiro no checkout, sem o dono reportar
    // via entregaPagamento — precisa creditar o caixa físico do mesmo jeito.
    if (!entregaPagamento?.dinheiro && pedido.payment_method === 'cash') {
      await this.salaoService.registrarEntradaCaixa(restaurantId, `Venda delivery em dinheiro (entrega própria) - Pedido #${pedidoId}`, pedido.total, 'venda_dinheiro');
    }

    return { ok: true, pedido_id: pedidoId, status: 'delivered', entrega_propria: true };
  }

  async registrarOcorrencia(
    pedidoId: number,
    motoboyId: number,
    tipo: 'pendente' | 'cancelada',
    motivo: string,
  ) {
    const { data: pedido } = await this.supabase.client
      .from('orders')
      .select('id, status')
      .eq('id', pedidoId)
      .eq('motoboy_id', motoboyId)
      .maybeSingle();
    if (!pedido) throw new NotFoundException('Pedido não encontrado ou não atribuído a você');

    const update: Record<string, any> = {
      delivery_notes: motivo.trim(),
      delivery_occurrence: tipo,
      updated_at: new Date().toISOString(),
    };
    if (tipo === 'cancelada') update.status = 'canceled';

    const { error } = await this.supabase.client
      .from('orders')
      .update(update)
      .eq('id', pedidoId);
    if (error) throw error;

    if (tipo === 'cancelada' && pedido.status !== 'canceled') {
      await this.estoque.restaurarItensDoPedido(pedidoId);
    }

    return { ok: true, pedido_id: pedidoId, tipo, status: update.status ?? pedido.status };
  }

  async pedidosDisponiveis(motoboyId: number, restaurantId: number) {
    await this.exigirAfiliacaoAceita(motoboyId, restaurantId);
    await this.exigirUsaMotoboy(restaurantId);

    const { data, error } = await this.supabase.client
      .from('orders')
      .select('id, total, status, payment_method, created_at, customer_id')
      .eq('restaurant_id', restaurantId)
      .eq('status', 'ready')
      .is('motoboy_id', null)
      .order('created_at', { ascending: true });
    if (error) throw error;

    const pedidos = await Promise.all(
      (data ?? []).map(async (p) => {
        const { data: c } = p.customer_id
          ? await this.supabase.client
              .from('customers')
              .select('name, phone_e164, address_json')
              .eq('id', p.customer_id)
              .maybeSingle()
          : { data: null };
        const { data: itensRaw } = await this.supabase.client
          .from('order_items')
          .select('id, quantity, unit_price, product_id')
          .eq('order_id', p.id);
        return { ...p, cliente: c, itens: itensRaw ?? [] };
      }),
