1	import React, { useState, useRef } from 'react';
2	import { uploadImagem } from '../../services/restauranteService';
3	import Icon from '../AppIcon';
4	
5	const MAX_MB = 5;
6	const ACCEPT = 'image/jpeg,image/jpg,image/png,image/webp,image/gif';
7	
8	/**
9	 * Props:
10	 *  value      — URL atual da imagem
11	 *  onChange   — (url: string) => void
12	 *  folder     — subpasta no bucket ('logos' | 'banners' | 'carrossel' | 'fundos')
13	 *  aspect     — proporção do preview: 'square' | 'wide' | 'banner'
14	 *  placeholder — texto no input URL
15	 *  uploadFn   — (file, folder) => Promise<{ url }> — default é o upload do dono de
16	 *               restaurante; passe outra função (ex. upload de admin) quando o contexto
17	 *               não for uma loja (ex. branding da plataforma).
18	 *  previewOpacity — 0-1, aplicada na miniatura pra refletir transparência configurável.
19	 */
20	const ImageUpload = ({ value, onChange, folder = 'geral', aspect = 'wide', placeholder = 'https://...', uploadFn = uploadImagem, previewOpacity }) => {
21	  const [tab, setTab] = useState('upload');
22	  const [urlInput, setUrlInput] = useState('');
23	  const [uploading, setUploading] = useState(false);
24	  const [progress, setProgress] = useState(0);
25	  const [erro, setErro] = useState(null);
26	  const [dragOver, setDragOver] = useState(false);
27	  const fileRef = useRef(null);
28	
29	  const previewH = aspect === 'square' ? 'h-32 w-32' : aspect === 'banner' ? 'h-32 w-full' : 'h-24 w-full';
30	
31	  const upload = async (file) => {
32	    setErro(null);
33	    if (!file.type.startsWith('image/')) { setErro('Apenas imagens (JPG, PNG, WEBP)'); return; }
34	    if (file.size > MAX_MB * 1024 * 1024) { setErro(`Máximo ${MAX_MB}MB`); return; }
35	
36	    setUploading(true);
37	    setProgress(20);
38	    try {
39	      setProgress(50);
40	      const result = await uploadFn(file, folder);
41	      setProgress(100);
42	      onChange(result.url);
43	    } catch (e) {
44	      setErro(e.message ?? 'Erro no upload');
45	    } finally {
46	      setUploading(false);
47	      setProgress(0);
48	      if (fileRef.current) fileRef.current.value = '';
49	    }
50	  };
51	
52	  const handleFile = (e) => { const f = e.target.files?.[0]; if (f) upload(f); };
53	  const handleDrop = (e) => { e.preventDefault(); setDragOver(false); const f = e.dataTransfer.files?.[0]; if (f) upload(f); };
54	  const handleUrlConfirm = () => { const u = urlInput.trim(); if (u) { onChange(u); setUrlInput(''); } };
